(function(){'use strict';var path=window.location.pathname;if(!/(pricing|terms)(\/|$)/.test(path))return;var locale=(document.documentElement.lang||'en').replace('_','-');var disclaimer=document.querySelector('.rate-disclaimer');var tooltip=disclaimer?disclaimer.textContent.replace(/\s+/g,' ').trim():'';var RATE_TTL=24*3600*1000;var GEO_TTL=7*24*3600*1000;var RATE_KEY='bst_usd_rates_v1';var GEO_KEY='bst_geo_v1';var PRICE_RE=/USD\s?(\d+(?:\.\d+)?)|US\$\s?(\d+(?:\.\d+)?)|(\d+(?:\.\d+)?)\s?USD|(\d+(?:\.\d+)?)\s?美元|(\d+(?:\.\d+)?)\s?دولار(?:ًا)?\s?أمريكي(?:ًا)?/;var CURRENCIES={US:'USD',CA:'CAD',GB:'GBP',AU:'AUD',NZ:'NZD',DE:'EUR',FR:'EUR',IT:'EUR',ES:'EUR',PT:'EUR',NL:'EUR',BE:'EUR',IE:'EUR',AT:'EUR',FI:'EUR',GR:'EUR',SK:'EUR',SI:'EUR',EE:'EUR',LV:'EUR',LT:'EUR',CY:'EUR',MT:'EUR',HR:'EUR',LU:'EUR',BG:'EUR',PL:'PLN',SE:'SEK',DK:'DKK',NO:'NOK',CH:'CHF',CZ:'CZK',HU:'HUF',RO:'RON',UA:'UAH',CN:'CNY',HK:'HKD',TW:'TWD',JP:'JPY',KR:'KRW',IN:'INR',PK:'PKR',BD:'BDT',LK:'LKR',VN:'VND',TH:'THB',MY:'MYR',ID:'IDR',PH:'PHP',SG:'SGD',KH:'KHR',LA:'LAK',MM:'MMK',NP:'NPR',MV:'MVR',BN:'BND',AE:'AED',SA:'SAR',QA:'QAR',KW:'KWD',OM:'OMR',BH:'BHD',JO:'JOD',EG:'EGP',MA:'MAD',DZ:'DZD',TN:'TND',IQ:'IQD',LB:'LBP',YE:'YER',IL:'ILS',PS:'ILS',RU:'RUB',KZ:'KZT',UZ:'UZS',TR:'TRY',AZ:'AZN',GE:'GEL',BY:'BYN',AM:'AMD',MD:'MDL',KG:'KGS',TJ:'TJS',TM:'TMT',BR:'BRL',MX:'MXN',AR:'ARS',CL:'CLP',CO:'COP',PE:'PEN',UY:'UYU',PY:'PYG',BO:'BOB',EC:'USD',CR:'CRC',PA:'USD',ZA:'ZAR',NG:'NGN',KE:'KES',GH:'GHS',ET:'ETB',TZ:'TZS',UG:'UGX',MW:'MWK',ZM:'ZMW',ZW:'ZWL'};function storeGet(key){try{var raw=window.localStorage.getItem(key);return raw?JSON.parse(raw):null;}catch(e){return null;}}function storeSet(key,val){try{window.localStorage.setItem(key,JSON.stringify(val));}catch(e){}}function getJSON(url){return new Promise(function(resolve,reject){var done=false;var req=new XMLHttpRequest();req.open('GET',url,true);req.timeout=8000;var timer=setTimeout(function(){if(!done){done=true;req.abort();reject(new Error('timeout'));}},8000);req.onreadystatechange=function(){if(req.readyState!==4||done)return;done=true;clearTimeout(timer);if(req.status>=200&&req.status<300){try{resolve(JSON.parse(req.responseText));}catch(e){reject(e);}}else{reject(new Error('status '+req.status));}};req.ontimeout=function(){if(!done){done=true;clearTimeout(timer);reject(new Error('timeout'));}};req.onerror=function(){if(!done){done=true;clearTimeout(timer);reject(new Error('network'));}};req.send();});}function lookupGeo(){var cached=storeGet(GEO_KEY);if(cached&&cached.currency&&Date.now()-cached.t<GEO_TTL){return Promise.resolve(cached.currency);}return getJSON('https://ipwho.is/').then(function(d){if(d&&d.success&&d.currency&&d.currency.code)return d.currency.code;throw new Error('geo');}).catch(function(){return getJSON('https://ipapi.co/json/').then(function(d){if(d&&d.currency)return d.currency;throw new Error('geo');});}).catch(function(){var tag=(navigator.language||'').split(/[-_]/);var region=(tag[1]||tag[0]||'').toUpperCase();return CURRENCIES[region]||'';}).then(function(code){if(code)storeSet(GEO_KEY,{t:Date.now(),currency:code});return code;});}function lookupRates(){var cached=storeGet(RATE_KEY);if(cached&&cached.rates&&Date.now()-cached.t<RATE_TTL){return Promise.resolve(cached.rates);}return getJSON('https://open.er-api.com/v6/latest/USD').then(function(d){if(d&&d.rates)return d.rates;throw new Error('rates');}).catch(function(){return getJSON('https://cdn.jsdelivr.net/npm/@fawazahmed0/currency-api@latest/v1/currencies/usd.min.json').then(function(d){if(d&&d.usd){var rates={};Object.keys(d.usd).forEach(function(k){rates[k.toUpperCase()]=d.usd[k];});return rates;}throw new Error('rates');});}).then(function(rates){storeSet(RATE_KEY,{t:Date.now(),rates:rates});return rates;});}function localText(usd,rates,currency){var rate=rates[currency]||rates[currency.toUpperCase()]||rates[currency.toLowerCase()];if(!rate||rate<=0)return'';var amount=usd*rate;try{var digits=amount>=10?0:2;return new Intl.NumberFormat(locale,{style:'currency',currency:currency,minimumFractionDigits:0,maximumFractionDigits:digits}).format(amount);}catch(e){return currency+' '+Math.round(amount);}}function insertLocalPrices(rates,currency){var usdFromMatch=function(m){for(var i=1;i<m.length;i++){if(m[i]!==undefined)return parseFloat(m[i]);}return NaN;};var root=document.querySelector('main')||document.body;var walker=document.createTreeWalker(root,NodeFilter.SHOW_TEXT,{acceptNode:function(n){var p=n.parentNode;if(!p)return NodeFilter.FILTER_REJECT;if(p.nodeName==='SCRIPT'||p.nodeName==='STYLE')return NodeFilter.FILTER_REJECT;if(p.hasAttribute&&p.hasAttribute('data-price'))return NodeFilter.FILTER_REJECT;if(p.className&&String(p.className).indexOf('local-price')!==-1)return NodeFilter.FILTER_REJECT;return NodeFilter.FILTER_ACCEPT;}});var nodes=[];while(walker.nextNode()){nodes.push(walker.currentNode);}nodes.forEach(function(node){var value=node.nodeValue;if(!value)return;var re=new RegExp(PRICE_RE.source,'g');var matches=[];var m;while((m=re.exec(value))!==null){matches.push(m);}if(!matches.length)return;var parent=node.parentNode;var frag=document.createDocumentFragment();var last=0;matches.forEach(function(m){var usd=usdFromMatch(m);frag.appendChild(document.createTextNode(value.slice(last,m.index)));var strong=document.createElement('strong');strong.textContent=m[0];frag.appendChild(strong);if(isFinite(usd)&&usd>0){var text=localText(usd,rates,currency);if(text){var span=document.createElement('span');span.className='local-price';span.textContent=text;if(tooltip)span.title=tooltip;frag.appendChild(document.createTextNode(' '));frag.appendChild(span);}}last=m.index+m[0].length;});frag.appendChild(document.createTextNode(value.slice(last)));parent.replaceChild(frag,node);});}Promise.all([lookupGeo(),lookupRates()]).then(function(res){var currency=String(res[0]||'').toUpperCase();var rates=res[1];if(!currency||currency==='USD'||!rates)return;insertLocalPrices(rates,currency);}).catch(function(){});})();